SELECT CAST(r.rule_id AS INTEGER) AS GR_Rule_ID, r.rule_nm AS GR_Rule_Nm, r.act_ind AS GR_Act_Ind, r.rule_group AS GR_Rule_Group, r.rule_variant AS GR_Rule_Variant, r.project_name AS GR_Project_Name, r.process_name AS GR_Process_Name, r.seq_no AS GR_Seq_No, r.sequencing_mode AS GR_Sequencing_Mode, r.on_failure AS GR_On_Failure, r.database_name AS GR_Database_Name, r.src_tbl_nm AS GR_Src_Tbl_Nm, r.sql_dialect AS GR_Sql_Dialect, CAST(SUBSTR(r.rule_syntax, 1, 4000) AS VARCHAR(4000)) AS GR_Rule_Syntax, r.src_key_cols AS GR_Src_Key_Cols, r.element_name AS GR_Element_Name, r.threshold_pct AS GR_Threshold_Pct, r.threshold_count AS GR_Threshold_Count, r.threshold_operator AS GR_Threshold_Operator, r.severity AS GR_Severity, r.universe_version AS GR_Universe_Version, r.universe_year AS GR_Universe_Year, r.dgr_nbr AS GR_Dgr_Nbr, r.issue_category_name AS GR_Issue_Category, r.business_rule AS GR_Business_Rule, r.rule_description AS GR_Rule_Description, r.load_datetime AS GR_Load_Dtts, r.last_updated_datetime AS GR_Last_Updated_Dtts, CASE WHEN r.act_ind = 1 THEN 'Active' ELSE 'Inactive' END AS GR_Active, CAST(1 AS INTEGER) AS GR_Rule_Cnt, CAST(1 AS INTEGER) AS GRE_Link
FROM HSABC_V.gre_rules r
WHERE UPPER(TRIM(r.rule_group)) LIKE 'ODAG1%'
